#!/usr/bin/env python3
"""Generate a full-body reference from Unity's Mecanim formulas.

This tool deliberately does not use the C++ runtime. It combines:

  * the source avatar generated by ``unity_humanoid_axes.py``
    (Unity UVW slots + local pre/post rotations),
  * the source skeleton's local rest rotations,
  * muscle curves from a Unity ``.anim`` file.

The pose formula is the one used by Unity 4.7's
``human::Human2SkeletonPose`` / ``skeleton::FromAxes``:

    local = rest * pre * ZYRoll(uvw) * post

where ``ZYRoll2Quat(x, y, z) = normalize(1, x, y + x*z, z - x*y)``.
``RootT`` / ``RootQ`` are copied directly to the Hips local transform, matching
``human::RetargetTo`` (``SkeletonPose.m_X[0] = m_RootX``); they are not deltas
from the rest pose. The four ``LeftFoot/RightFoot/LeftHand/RightHand`` goal T/Q
values are emitted as raw ``human::GetHumanPose`` data. The result is a small,
checked-in regression fixture for the C++ full-body test. It is not a
substitute for sampling a real Unity 2019 editor.
"""

from __future__ import annotations

import argparse
import json
import math
import re
from pathlib import Path


def q_mul(a, b):
    ax, ay, az, aw = a
    bx, by, bz, bw = b
    return [
        aw * bx + ax * bw + ay * bz - az * by,
        aw * by - ax * bz + ay * bw + az * bx,
        aw * bz + ax * by - ay * bx + az * bw,
        aw * bw - ax * bx - ay * by - az * bz,
    ]


def q_norm(q):
    n = math.sqrt(sum(v * v for v in q))
    if n <= 1e-12:
        return [0.0, 0.0, 0.0, 1.0]
    return [v / n for v in q]


def zy_roll(x, y, z):
    return q_norm([x, y + x * z, z - x * y, 1.0])


def half_tan(degrees):
    angle = math.radians(degrees)
    limit = math.pi * 0.5 - 1e-6
    return math.tan(max(-limit, min(limit, angle * 0.5)))


def muscle_angle(value, minimum, maximum):
    value = max(-1.0, min(1.0, value))
    return value * maximum if value >= 0.0 else value * (-minimum)


def load_json(path):
    return json.loads(Path(path).read_text(encoding="utf-8"))


def parse_anim_curves(path):
    """Read the m_FloatCurves block of a Unity .anim file.

    The anim files used here are flat YAML. This intentionally avoids a PyYAML
    dependency; it only understands the subset needed for float curves.
    Returns ``(curves, wrap_modes)``; each curve is a list of keys and each wrap
    pair is ``(pre, post)`` using Unity's WrapMode values.
    """
    text = Path(path).read_text(encoding="utf-8")
    start = text.index("\n  m_FloatCurves:")
    end = text.index("\n  m_AnimationClipSettings:", start)
    block = text[start:end]

    item_starts = [m.start() for m in re.finditer(r"(?m)^  - curve:", block)]
    curves = {}
    wrap_modes = {}
    for n, item_start in enumerate(item_starts):
        item_end = item_starts[n + 1] if n + 1 < len(item_starts) else len(block)
        item = block[item_start:item_end]

        attribute = re.search(r"(?m)^    attribute:[ \t]*(.*?)[ \t]*$", item)
        if attribute is None:
            continue
        name = attribute.group(1)
        if not name:
            continue

        curve_start = item.index("m_Curve:")
        curve_end = item.index("m_PreInfinity:", curve_start)
        curve_block = item[curve_start:curve_end]

        keys = []
        key_starts = [
            m.start()
            for m in re.finditer(r"(?m)^      - serializedVersion:", curve_block)
        ]
        for k, key_start in enumerate(key_starts):
            key_end = key_starts[k + 1] if k + 1 < len(key_starts) else len(curve_block)
            key = curve_block[key_start:key_end]

            def field(name):
                match = re.search(r"(?m)^        " + name + r":[ \t]*([^\s]+)", key)
                if match is None:
                    raise ValueError("missing keyframe field {} in {}".format(name, path))
                return float(match.group(1))

            keys.append({
                "time": field("time"),
                "value": field("value"),
                "inSlope": field("inSlope"),
                "outSlope": field("outSlope"),
            })

        if not keys:
            continue
        keys.sort(key=lambda key: key["time"])
        curves[name] = keys

        def wrap_mode(field):
            match = re.search(r"(?m)^      " + field + r":[ \t]*([0-9]+)", item)
            return int(match.group(1)) if match else 8

        wrap_modes[name] = (wrap_mode("m_PreInfinity"),
                            wrap_mode("m_PostInfinity"))
    return curves, wrap_modes


def wrap_time(time, lo, hi, mode):
    span = hi - lo
    if span <= 0.0:
        return lo
    if mode == 2:  # Loop
        t = math.fmod(time - lo, span)
        if t < 0.0:
            t += span
        return lo + t
    if mode == 4:  # PingPong
        period = span * 2.0
        t = math.fmod(time - lo, period)
        if t < 0.0:
            t += period
        if t > span:
            t = period - t
        return lo + t
    return max(lo, min(hi, time))


def evaluate_curve(keys, time, pre_wrap=8, post_wrap=8):
    if not keys:
        return 0.0
    if len(keys) == 1:
        return keys[0]["value"]

    lo = keys[0]["time"]
    hi = keys[-1]["time"]
    if not hi > lo:
        return keys[0]["value"]

    t = time
    if t < lo:
        t = wrap_time(time, lo, hi, pre_wrap)
    elif t > hi:
        t = wrap_time(time, lo, hi, post_wrap)

    if t <= lo:
        return keys[0]["value"]
    if t >= hi:
        return keys[-1]["value"]

    upper = len(keys)
    for i, key in enumerate(keys):
        if key["time"] > t:
            upper = i
            break
    if upper == 0:
        return keys[0]["value"]

    k0 = keys[upper - 1]
    k1 = keys[upper]
    dt = k1["time"] - k0["time"]
    if dt <= 0.0:
        return k0["value"]
    u = (t - k0["time"]) / dt
    u2 = u * u
    u3 = u2 * u
    h00 = 2.0 * u3 - 3.0 * u2 + 1.0
    h10 = u3 - 2.0 * u2 + u
    h01 = -2.0 * u3 + 3.0 * u2
    h11 = u3 - u2
    return (
        h00 * k0["value"]
        + h10 * dt * k0["outSlope"]
        + h01 * k1["value"]
        + h11 * dt * k1["inSlope"]
    )


def curve_value(curves, wrap_modes, name, time, fallback):
    keys = curves.get(name)
    if not keys:
        return fallback
    pre_wrap, post_wrap = wrap_modes.get(name, (8, 8))
    return evaluate_curve(keys, time, pre_wrap, post_wrap)


def root_transform(curves, wrap_modes, time):
    root_t = [
        curve_value(curves, wrap_modes, "RootT." + axis, time, 0.0)
        for axis in ("x", "y", "z")
    ]
    root_q = q_norm([
        curve_value(curves, wrap_modes, "RootQ." + axis, time, fallback)
        for axis, fallback in (("x", 0.0), ("y", 0.0), ("z", 0.0), ("w", 1.0))
    ])
    return root_t, root_q


def goal_transforms(curves, wrap_modes, time):
    """Read the raw Unity goals (LeftFoot/RightFoot/LeftHand/RightHand)."""
    goals = {}
    for name in ("LeftFoot", "RightFoot", "LeftHand", "RightHand"):
        t = [
            curve_value(curves, wrap_modes, name + "T." + axis, time, 0.0)
            for axis in ("x", "y", "z")
        ]
        q = q_norm([
            curve_value(curves, wrap_modes, name + "Q." + axis, time, fallback)
            for axis, fallback in (("x", 0.0), ("y", 0.0), ("z", 0.0), ("w", 1.0))
        ])
        goals[name] = {"t": t, "q": q}
    return goals


def source_pose(skeleton, avatar, muscles, curves, wrap_modes, time):
    """Return local rotations, the Hips root xform, and raw IK goals."""
    rest_by_name = {bone["name"]: bone["rotation"] for bone in skeleton["bones"]}
    muscle_ids = {entry["name"]: i for i, entry in enumerate(muscles["entries"])}
    values = muscles["values"]

    result = {}
    for human_name, bone_name in avatar["bones"].items():
        rest = q_norm(rest_by_name[bone_name])
        local = rest

        if human_name in avatar.get("preRot", {}):
            local = q_mul(local, q_norm(avatar["preRot"][human_name]))

        uvw = avatar.get("uvw", {}).get(human_name)
        if uvw is not None:
            xyz = [0.0, 0.0, 0.0]
            for slot in range(3):
                binding = uvw[slot]
                if binding is None:
                    continue
                muscle_id = muscle_ids[binding["muscle"]]
                angle = muscle_angle(
                    values[muscle_id], binding["min"], binding["max"]
                )
                xyz[slot] = half_tan(angle) * binding["sign"]
            local = q_mul(local, zy_roll(xyz[0], xyz[1], xyz[2]))

        if human_name in avatar.get("postRot", {}):
            local = q_mul(local, q_norm(avatar["postRot"][human_name]))

        result[human_name] = local

    # Unity's root is SkeletonPose.m_X[0] (the Hips); Human2SkeletonPose skips
    # Hips and RetargetTo assigns m_RootX directly. RootT/RootQ are therefore
    # absolute local values, not rest-relative offsets.
    root_t, root_q = root_transform(curves, wrap_modes, time)
    if "Hips" in result:
        result["Hips"] = root_q
    return result, root_t, root_q, goal_transforms(curves, wrap_modes, time)


def main():
    parser = argparse.ArgumentParser()
    parser.add_argument("--avatar", required=True)
    parser.add_argument("--skeleton", required=True)
    parser.add_argument("--anim", required=True)
    parser.add_argument("--out", required=True)
    parser.add_argument(
        "--times",
        default="0,0.25,0.5,0.75,1.0",
        help="comma separated sample times",
    )
    args = parser.parse_args()

    avatar = load_json(args.avatar)
    skeleton = load_json(args.skeleton)
    curves, wrap_modes = parse_anim_curves(args.anim)

    # The source avatar has 92/95 muscle names depending on the model. Use the
    # actual UVW bindings; the C++ loader validates each name against its table.
    from_avatar = set()
    for slots in avatar.get("uvw", {}).values():
        for slot in slots:
            if slot is not None:
                from_avatar.add(slot["muscle"])
    if not from_avatar:
        raise SystemExit("avatar has no uvw muscle bindings")

    # Preserve a deterministic order: sorted names. This is only a fixture,
    # not the runtime muscle indexing.
    all_names = sorted(from_avatar)
    times = [float(value) for value in args.times.split(",")]

    samples = []
    for time in times:
        values_by_name = {
            name: curve_value(
                curves, wrap_modes, name, time, 0.0
            )
            for name in all_names
        }
        values = [values_by_name[name] for name in all_names]
        bones, root_t, root_q, goals = source_pose(
            skeleton,
            avatar,
            {
                "entries": [{"name": name} for name in all_names],
                "values": values,
            },
            curves,
            wrap_modes,
            time,
        )
        samples.append({
            "time": time,
            "muscles": values_by_name,
            "rootT": root_t,
            "rootQ": root_q,
            "goals": goals,
            "bones": bones,
        })

    Path(args.out).write_text(
        json.dumps(
            {
                "source": str(Path(args.anim).name),
                "avatar": str(Path(args.avatar).name),
                "skeleton": str(Path(args.skeleton).name),
                "muscleNames": all_names,
                "samples": samples,
            },
            indent=2,
        )
        + "\n",
        encoding="utf-8",
    )
    print(
        "wrote {} ({} muscles, {} bones, {} samples)".format(
            args.out, len(all_names), len(samples[0]["bones"]), len(samples)
        )
    )


if __name__ == "__main__":
    main()
